import React from 'react';
import { ChakraProvider, extendTheme, Heading, Container, VStack } from '@chakra-ui/react';
import { NoteEditor } from './components/Editor';
import { NoteList } from './components/List';

const theme = extendTheme({}); // you can customize this if needed

const App: React.FC = () => {
  return (
    <ChakraProvider theme={theme}>
      <Container maxW="container.md" py={8}>
        <VStack spacing={6} align="stretch">
          <Heading as="h1" size="xl" textAlign="center">
            Smart Notes
          </Heading>
          <NoteEditor />
          <NoteList />
        </VStack>
      </Container>
    </ChakraProvider>
  );
};

export default App;
